import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const f=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),s={name:"guide/introduction.md"};function n(i,t,l,d,c,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>FlowPilot runs gameplay flows made of <strong>Tasks</strong>. A flow is a FlowPilot asset: a tree of Tasks that an Actor runs through a <a href="/reference/components/flowpilot-component">FlowPilot Component</a>. Use it for level scripting (music, fades, spawns, level streaming, win and lose conditions) or for local logic such as interactive objects.</p><p>If you know Behavior Trees, the ideas are the same: a Sequence runs its Tasks until one fails, a Selector runs them until one succeeds.</p><h2 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core concepts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>What it is</th></tr></thead><tbody><tr><td><a href="/reference/core/flowpilot-asset">FlowPilot Asset</a></td><td>A data asset holding the flow. Its Root is a Sequence.</td></tr><tr><td><a href="/reference/components/flowpilot-component">FlowPilot Component</a></td><td>Runs a FlowPilot asset on an Actor. Start, pause and stop it from Blueprint, or auto start it.</td></tr><tr><td><a href="/reference/core/flowpilot-task">Task</a></td><td>One step of the flow. It starts, runs for as long as it needs, then succeeds or fails.</td></tr><tr><td><a href="/reference/core/flow-actor-reference">Flow Actor Reference</a></td><td>How Tasks point at Actors: <strong>Self</strong>, an Actor <strong>In Level</strong>, or Actors found at <strong>Runtime</strong> by GameplayTag.</td></tr><tr><td><a href="/reference/components/flowpilot-subsystem">FlowPilot Subsystem</a></td><td>Tracks every FlowPilot Component and caches Actors found by GameplayTag.</td></tr></tbody></table><h2 id="tasks-that-organise-other-tasks" tabindex="-1">Tasks that organise other Tasks <a class="header-anchor" href="#tasks-that-organise-other-tasks" aria-label="Permalink to &quot;Tasks that organise other Tasks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Runs its Tasks</th><th>Succeeds when</th></tr></thead><tbody><tr><td><a href="/reference/tasks/sequence">Sequence</a></td><td>One after another</td><td>All succeed. Stops at the first failure.</td></tr><tr><td><a href="/reference/tasks/selector">Selector</a></td><td>One after another</td><td>One succeeds. Stops at the first success.</td></tr><tr><td><a href="/reference/tasks/parallel">Parallel</a></td><td>All at once</td><td>Depends on its Completion Type (any/all succeed or fail).</td></tr><tr><td><a href="/reference/tasks/loop">Loop</a></td><td>Its single Task, N times or forever</td><td>All iterations succeed.</td></tr><tr><td><a href="/reference/tasks/sub-flow">Sub Flow</a></td><td>Another FlowPilot asset</td><td>That asset&#39;s flow succeeds.</td></tr></tbody></table><p>Disabled Tasks are skipped. Every Task, built-in or your own, is listed in the <a href="/reference/">Reference</a>.</p><h2 id="what-s-included" tabindex="-1">What&#39;s included <a class="header-anchor" href="#what-s-included" aria-label="Permalink to &quot;What&#39;s included&quot;">​</a></h2><ul><li><strong>Content example map:</strong> try each Task on its own.</li><li><strong>Game map template:</strong> a full level using streaming levels, spawning, gating, a simple character, progression and UI notifications.</li><li><strong>Tag Actor Component:</strong> tags Actors so flows can find them by GameplayTag.</li><li><strong>Example Component:</strong> barebones health and inventory used by the game map template.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./getting-started">Getting Started</a>: build and run your first flow.</li><li><a href="./tutorial-spawn-ai">Tutorial: Spawn an AI</a>: a hands-on walkthrough in the tutorial level.</li><li><a href="./debugging">Debugging Flows</a>: watch flows run, breakpoints and the in-game overlay.</li><li><a href="./custom-tasks">Creating Your Own Task</a>: extend FlowPilot in Blueprint or C++.</li></ul><p>Questions or ideas: <a href="https://discord.gg/sF9KjZ9qqj" target="_blank" rel="noreferrer">Discord</a> or <a href="https://github.com/Mikea15/UEFlowPilot/issues" target="_blank" rel="noreferrer">GitHub issues</a>.</p>',13)])])}const p=e(s,[["render",n]]);export{f as __pageData,p as default};
